<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import type { Order } from './types'
const props = withDefaults(defineProps<{ orders: Order[]; busy: boolean; pageSize?: number }>(), { pageSize: 8 })
defineEmits<{ resume: [order: Order]; recheck: [order: Order] }>()
const page = ref(1), pages = computed(() => Math.max(1,Math.ceil(props.orders.length/props.pageSize)))
watch(pages, n => {page.value=Math.min(page.value,n)})
const rows = computed(() => props.orders.slice((page.value-1)*props.pageSize,page.value*props.pageSize))
const time = (s:string) => new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const money = (n:number) => (n/100).toFixed(2)
const credit = (o:Order) => o.credited_credit ?? (o.status==='paid' ? o.credit : null)
const label = (o:Order) => o.reversed_at ? '已退款' : o.status==='paid' ? '已到账' : o.gateway_status==='expired' ? '已过期' : '待支付'
const copied = ref('')
async function copyChannelNo(o: Order) {
 if (!o.channel_trade_no) return
 try { await navigator.clipboard.writeText(o.channel_trade_no) } catch { const area=document.createElement('textarea'); area.value=o.channel_trade_no; document.body.appendChild(area); area.select(); document.execCommand('copy'); area.remove() }
 copied.value=o.id; setTimeout(() => { if (copied.value===o.id) copied.value='' }, 1200)
}
</script>
<template><div class="order-list"><div class="table-wrap"><table><thead><tr><th>订单 / 时间</th><th>支付方式 / 渠道单号</th><th>应付 / 实付</th><th>到账 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td><code :title="o.id">{{ o.id.slice(0,10) }}…{{ o.id.slice(-4) }}</code><small>{{ time(o.created_at) }}</small></td><td><strong>{{ o.payment_type==='wxpay' ? '微信支付' : '支付宝' }}</strong><button v-if="o.channel_trade_no" class="channel-no" :title="`复制 ${o.channel_trade_no}`" @click="copyChannelNo(o)">{{ copied===o.id ? '已复制' : o.channel_trade_no }}</button><small v-else>渠道单号待生成</small></td><td><strong>¥{{ money(o.amount_cents) }}</strong><small>{{ o.paid_amount_cents != null ? `实付 ¥${money(o.paid_amount_cents)}` : '尚未确认收款' }}</small></td><td><strong :class="{ green:o.status==='paid' && !o.reversed_at }">{{ credit(o) != null ? `$${Number(credit(o))}` : '—' }}</strong><small class="status" :class="{ green:o.status==='paid' && !o.reversed_at }">{{ label(o) }}</small></td><td><div v-if="o.status==='pending'" class="actions"><button v-if="o.gateway_status!=='expired'" :disabled="busy" @click="$emit('resume',o)">继续支付</button><button :disabled="busy" @click="$emit('recheck',o)">查到账</button></div><span v-else class="done">{{ o.reversed_at ? '已冲正' : '自动入账 ✓' }}</span></td></tr></tbody></table></div><p v-if="!orders.length" class="empty">暂无充值订单，选择上方套餐开始充值。</p><div class="pagination"><span>共 {{ orders.length }} 笔 · {{ page }} / {{ pages }} 页</span><div><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page>=pages" @click="page++">下一页</button></div></div></div></template>
<style scoped>
.order-list{color:#1c2333;color-scheme:light}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-weight:500;color:#8a94a8;background:#f8fcfb;padding:11px 18px;white-space:nowrap;font-size:12px}td{padding:13px 18px;border-bottom:1px solid #f1f6f5;line-height:1.5;vertical-align:middle}tbody tr{transition:background .15s}tbody tr:hover{background:#fbfefd}code{font-size:12px;color:#3d4a63;white-space:nowrap;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}strong{font-weight:650;color:#1c2333;font-size:14px;white-space:nowrap}small{display:block;color:#8a94a8;font-size:12px;margin-top:3px;white-space:nowrap}.channel-no{display:block;padding:0;margin-top:3px;border:0;background:transparent;color:#d14f4f;font-size:12px;max-width:190px;overflow:hidden;text-overflow:ellipsis;cursor:pointer}.green{color:#1f9d63}small.status{display:inline-block;margin-top:5px;padding:1px 8px;border-radius:999px;background:#f2f7f6;color:#6f7a90;font-size:11px}small.status.green{background:#e8f8ef;color:#1f9d63}.done{color:#8a94a8;font-size:12px;white-space:nowrap}.actions{display:flex;gap:6px;flex-wrap:wrap}button{font-size:12px;color:#15c18d;background:#f0fdf9;border:1px solid #dffbf3;padding:6px 11px;border-radius:8px;white-space:nowrap;cursor:pointer;font-weight:600}button:hover:not(:disabled){background:#e5fcf5}button:disabled{opacity:.35;cursor:not-allowed}.pagination{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;font-size:12px;color:#8a94a8;gap:10px}.pagination>div{display:flex;gap:6px}.pagination button{color:#4d5a73;background:#fff;border-color:#e4efec;font-weight:500;padding:5px 11px}.empty{padding:34px 16px;text-align:center;font-size:13px;color:#8a94a8;margin:0}@media(max-width:680px){td,th{padding:11px 12px}.actions{flex-direction:column}code{font-size:11px}}
</style>
